@Tags(['golden'])
library;

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:zaghlol/features/accounts/domain/account.dart';
import 'package:zaghlol/features/accounts/presentation/edit_card/card_details_screen.dart';

import '../../../support/golden_matrix.dart';
import 'edit_card_test.dart' as base;

// Goldens are generated by CI (`--update-goldens`); PNGs are not committed.
void main() {
  for (final v in goldenVariants) {
    testWidgets('edit card (create credit) golden ${v.name}', (t) async {
      await t.binding.setSurfaceSize(const Size(390, 900));
      addTearDown(() => t.binding.setSurfaceSize(null));
      await t.pumpWidget(
        base.host(
          CardDetailsScreen.create(
            kind: AccountKind.credit,
            institution: base.banks.first,
          ),
          repo: base.FakeRepo([]),
          locale: v.locale,
          dark: v.dark,
        ),
      );
      await t.pumpAndSettle();
      await expectLater(
        find.byType(MaterialApp),
        matchesGoldenFile('../../../goldens/edit_card_${v.name}.png'),
      );
    });
  }
}
